if (!$json.output?.extraction) {
  throw new Error('El resolver ERP/API no devolvio output.extraction.');
}
if (!$json.ingest_payload) {
  throw new Error('El resolver ERP/API no devolvio ingest_payload.');
}
return [{ json: $json }];

const binaryKey = 'attachment_0';
const binary = $binary?.[binaryKey];
if (!binary) {
  throw new Error('El email debe tener exactamente un adjunto PDF en attachment_0.');
}

const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
const fromValue = typeof $json.from === 'object'
  ? ($json.from?.value?.[0]?.address ?? $json.from?.text ?? null)
  : ($json.from ?? null);

return [
  {
    json: {
      source: 'campojoyma-email',
      pdf_base64: buffer.toString('base64'),
      pdf_nombre: binary.fileName || 'factura-email.pdf',
      pdf_mime_type: binary.mimeType || 'application/pdf',
      pdf_size: buffer.length,
      email: {
        from: fromValue,
        subject: $json.subject ?? null,
        date: $json.date ?? null,
      },
    },
  },
];

const input = $json;
const source = input.source ?? {};
const triggerChannel = source.trigger_channel === 'email' ? 'email' : 'webhook';
const ai = input.ai ?? {};
const literal = ai.extraction ?? {};
const metadata = ai.metadata ?? {};
const warnings = [...(Array.isArray(metadata.warnings) ? metadata.warnings : [])];
const evidence = {};
const getVar = (name) => {
  if (typeof $vars === 'undefined') return null;
  const value = $vars?.[name];
  return value === undefined || value === null || String(value).trim() === '' ? null : value;
};
const readString = (value) => typeof value === 'string' && value.trim() ? value.trim() : null;
const readNumber = (value, fallback = null) => {
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  if (typeof value === 'string' && value.trim()) {
    const parsed = Number(value.replace(/\s/g, '').replace(/\.(?=\d{3}(\D|$))/g, '').replace(',', '.'));
    return Number.isFinite(parsed) ? parsed : fallback;
  }
  return fallback;
};
const readInteger = (value, fallback = null) => {
  const parsed = readNumber(value, fallback);
  return parsed === null || parsed === undefined ? fallback : Math.trunc(parsed);
};
const firstValue = (sourceObject, keys) => {
  if (!sourceObject || typeof sourceObject !== 'object') return null;
  for (const key of keys) {
    const value = sourceObject[key];
    if (value !== undefined && value !== null && String(value).trim() !== '') return value;
  }
  return null;
};
const normalizeNif = (value) => readString(value)?.toUpperCase().replace(/[^A-Z0-9]/g, '') ?? null;
const normalizeText = (value) => readString(value)?.toLocaleLowerCase('es-ES').normalize('NFD').replace(/[\u0300-\u036f]/g, '') ?? null;
const round2 = (value) => Math.round((Number(value) + Number.EPSILON) * 100) / 100;
const itemsFromResponse = (value) => {
  if (Array.isArray(value)) return value;
  if (!value || typeof value !== 'object') return [];
  if (Array.isArray(value.items)) return value.items;
  if (Array.isArray(value.data)) return value.data;
  if (Array.isArray(value.datos)) return value.datos;
  if (value.datos && typeof value.datos === 'object') return [value.datos];
  if (value.item && typeof value.item === 'object') return [value.item];
  return [value];
};
const apiBase = readString(getVar('CAMPOJOYMA_API_BASE_URL')) || 'http://172.19.0.1:18000';
const apiHeaders = { Accept: 'application/json' };
const apiGetResult = async (path, params = {}) => {
  const url = new URL(String(path).replace(/^\//, ''), apiBase.replace(/\/$/, '') + '/');
  for (const [key, value] of Object.entries(params)) {
    if (value !== null && value !== undefined && String(value) !== '') url.searchParams.set(key, String(value));
  }
  try {
    const data = await this.helpers.httpRequest({ method: 'GET', url: url.toString(), json: true, headers: apiHeaders });
    return { ok: true, data, error: null };
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    warnings.push('Error API ' + url.pathname + ': ' + message);
    return { ok: false, data: null, error: message };
  }
};
const apiGet = async (path, params = {}) => (await apiGetResult(path, params)).data;
const normalizeProvider = (item, catalogSource) => {
  if (!item || typeof item !== 'object') return null;
  const isAgricultor = catalogSource === 'api:/agricultores';
  return {
    proveedor_nombre: readString(firstValue(item, ['proveedor_nombre', 'nombre', 'ACR_Nombre', 'AGR_Nombre', 'name', 'Nombre'])),
    proveedor_nif: readString(firstValue(item, ['proveedor_nif', 'nif', 'cif', 'ACR_Nif', 'AGR_Nif', 'tax_id', 'NIF'])),
    FRR_idproveedor: isAgricultor ? null : readInteger(firstValue(item, ['FRR_idproveedor', 'ACR_Codigo', 'codigo', 'id'])),
    agricultor_id: isAgricultor ? readInteger(firstValue(item, ['AGR_Codigo', 'AGR_id', 'codigo', 'id'])) : null,
    FRR_idcuenta: isAgricultor ? null : readString(firstValue(item, ['FRR_idcuenta', 'ACR_Cuenta', 'ACR_CtaContable', 'cuenta', 'cuenta_contable'])),
    cuenta_gasto: isAgricultor ? null : readString(firstValue(item, ['cuenta_gasto', 'ACR_CuentaGasto', 'ACR_CtaGasto', 'FRR_ctagasto1', 'TPA_cuentagasto1'])),
    catalog_source: catalogSource,
    raw: item,
  };
};
const loadProviderCandidates = async (path, params) => {
  const result = await apiGetResult(path, params);
  return {
    ok: result.ok,
    error: result.error,
    candidates: result.ok
      ? itemsFromResponse(result.data).map((item) => normalizeProvider(item, 'api:' + path)).filter(Boolean)
      : [],
  };
};
const mergeProviderCandidates = (...groups) => {
  const unique = new Map();
  for (const provider of groups.flat()) {
    const identity = provider.catalog_source === 'api:/agricultores' ? provider.agricultor_id : provider.FRR_idproveedor;
    const key = [provider.catalog_source, identity ?? '', normalizeNif(provider.proveedor_nif) ?? '', normalizeText(provider.proveedor_nombre) ?? ''].join('|');
    if (!unique.has(key)) unique.set(key, provider);
  }
  return [...unique.values()];
};
const summarizeManualCandidate = (provider) => ({
  source: provider.catalog_source,
  agricultor_id: provider.agricultor_id,
  proveedor_nombre: provider.proveedor_nombre,
  proveedor_nif: provider.proveedor_nif,
});
const exactProviderMatches = (candidates, by, expected) => candidates.filter((provider) => (
  by === 'nif'
    ? normalizeNif(provider.proveedor_nif) === expected
    : normalizeText(provider.proveedor_nombre) === expected
));
const resolveProviderQuery = async ({ by, value, params }) => {
  const expected = by === 'nif' ? normalizeNif(value) : normalizeText(value);
  const query = { by, value, sources: [], exact_counts: { acreedores: 0, agricultores: 0 } };
  const acreedoresResult = await loadProviderCandidates('/acreedores', params);
  query.sources.push({ path: '/acreedores', ok: acreedoresResult.ok });
  if (!acreedoresResult.ok) {
    warnings.push('No se consulta /agricultores porque fallo el catalogo prioritario /acreedores.');
    return { terminal: true, provider: null, query, candidates: [], manualCandidates: [], reason: 'acreedores_error' };
  }

  const exactAcreedores = exactProviderMatches(acreedoresResult.candidates, by, expected);
  query.exact_counts.acreedores = exactAcreedores.length;
  if (exactAcreedores.length === 1) {
    return { terminal: true, provider: exactAcreedores[0], query, candidates: acreedoresResult.candidates, manualCandidates: [], reason: 'acreedor_exact' };
  }
  if (exactAcreedores.length > 1) {
    warnings.push('Hay ' + exactAcreedores.length + ' coincidencias exactas en /acreedores; no se elige una arbitrariamente.');
    return { terminal: true, provider: null, query, candidates: acreedoresResult.candidates, manualCandidates: [], reason: 'acreedores_ambiguous' };
  }

  const agricultoresResult = await loadProviderCandidates('/agricultores', params);
  query.sources.push({ path: '/agricultores', ok: agricultoresResult.ok });
  const candidates = mergeProviderCandidates(acreedoresResult.candidates, agricultoresResult.candidates);
  if (!agricultoresResult.ok) {
    return { terminal: true, provider: null, query, candidates, manualCandidates: [], reason: 'agricultores_error' };
  }

  const exactAgricultores = exactProviderMatches(agricultoresResult.candidates, by, expected);
  query.exact_counts.agricultores = exactAgricultores.length;
  if (exactAgricultores.length > 0) {
    warnings.push(exactAgricultores.length === 1
      ? 'Hay una coincidencia exacta en /agricultores, pero queda como candidato manual porque no existe una relacion AGR a ACR verificada.'
      : 'Hay ' + exactAgricultores.length + ' coincidencias exactas en /agricultores; quedan como candidatos manuales y no se elige una arbitrariamente.');
    return {
      terminal: true,
      provider: null,
      query,
      candidates,
      manualCandidates: exactAgricultores.map(summarizeManualCandidate),
      reason: exactAgricultores.length === 1 ? 'agricultor_manual' : 'agricultores_ambiguous',
    };
  }

  return { terminal: false, provider: null, query, candidates, manualCandidates: [], reason: 'no_exact_match' };
};
const chooseProvider = async () => {
  const nif = normalizeNif(literal.proveedor_nif);
  const nombre = readString(literal.proveedor_nombre);
  const attempts = [];
  let candidates = [];
  let manualCandidates = [];
  if (nif) {
    const result = await resolveProviderQuery({ by: 'nif', value: nif, params: { nif, limit: 10 } });
    attempts.push(result.query);
    candidates = mergeProviderCandidates(candidates, result.candidates);
    manualCandidates = [...manualCandidates, ...result.manualCandidates];
    if (result.terminal) return { ...result, attempts, candidates, manualCandidates };
  }
  if (nombre) {
    const result = await resolveProviderQuery({ by: 'nombre', value: nombre, params: { q: nombre, limit: 10 } });
    attempts.push(result.query);
    candidates = mergeProviderCandidates(candidates, result.candidates);
    manualCandidates = [...manualCandidates, ...result.manualCandidates];
    return { ...result, attempts, candidates, manualCandidates };
  }
  warnings.push(nif
    ? 'No se encontro una coincidencia exacta unica por NIF o nombre.'
    : 'La IA no encontro NIF ni nombre de proveedor para buscarlo.');
  return { provider: null, query: attempts.at(-1) ?? null, attempts, candidates, manualCandidates, reason: 'missing_or_no_exact_match' };
};
const resolveEmpresa = async () => {
  const envEmpresa = readInteger(getVar('CAMPOJOYMA_EMPRESA_ID'));
  if (envEmpresa) return { id: envEmpresa, evidence: { source: 'env', value: envEmpresa } };
  const empresas = itemsFromResponse(await apiGet('/empresas', { limit: 5 }));
  const first = empresas[0] ?? null;
  const id = readInteger(firstValue(first, ['EMP_idempresa', 'empresa_id', 'id', 'FRR_Idempresa']), 1);
  if (!first) warnings.push('No se pudo leer /empresas; se usa empresa 1 como fallback operativo.');
  return { id, evidence: { source: first ? 'api:/empresas' : 'fallback', raw: first } };
};
const resolveEjercicio = () => {
  const ejercicio = readInteger(getVar('CAMPOJOYMA_EJERCICIO'));
  if (!ejercicio) {
    warnings.push('Falta CAMPOJOYMA_EJERCICIO en n8n; no se deriva desde el ano calendario para evitar ejercicios ERP erroneos.');
    return { value: null, evidence: { source: 'missing_env' } };
  }
