  if (fromProvider) return { value: fromProvider, evidence: { source: provider?.catalog_source ?? 'provider', value: fromProvider } };
  const nif = normalizeNif(provider?.proveedor_nif ?? literal.proveedor_nif);
  const q = nif || provider?.proveedor_nombre || literal.proveedor_nombre;
  if (!q) return { value: null, evidence: { source: 'missing_query' } };
  const cuentas = itemsFromResponse(await apiGet('/cuentas-contables', nif ? { nif, limit: 5 } : { q, limit: 5 }));
  const unique = [...new Set(cuentas.map((item) => readString(firstValue(item, ['cuenta', 'codigo', 'CUC_Cuenta', 'CON_Cuenta', 'idcuenta']))).filter(Boolean))];
  if (unique.length === 1) return { value: unique[0], evidence: { source: 'api:/cuentas-contables', query: q } };
