  const normalized = catalog.map((item) => ({ id: readInteger(firstValue(item, ['FRR_idregimen', 'idregimen', 'regimen_id', 'id', 'TIV_idtipoiva', 'codigo'])), iva: readNumber(firstValue(item, ['iva', 'IVA', 'porcentaje', 'TIV_IVA', 'tipo_iva', 'FRR_iva1'])), raw: item })).filter((item) => item.id !== null);
