  const values = tipos.map((item) => readString(firstValue(item, ['FRR_tipofactura', 'tipo', 'codigo', 'value']))).filter(Boolean);
  if (visible) {
    const exact = values.find((value) => value.toUpperCase() === visible.toUpperCase());
    if (exact) return { value: exact, evidence: { source: 'pdf+api', visible } };
    warnings.push('El tipo factura visible no existe en catalogo; se deja pendiente.');
  }
  if (envDefault) {
    warnings.push('Se usa CAMPOJOYMA_TIPO_FACTURA_DEFAULT configurado en n8n.');
