  const envDefault = readString(getVar('CAMPOJOYMA_CUENTA_GASTO_DEFAULT'));
  if (envDefault) {
    warnings.push('Se usa CAMPOJOYMA_CUENTA_GASTO_DEFAULT; revisar si aplica al proveedor.');
    return { value: envDefault, evidence: { source: 'env', value: envDefault } };
  }
